# Lab 4 — (B) bảng tra tự làm từ CHÍNH bộ mẫu: mọi cặp (kênh, provider, Event ID) có trong 40 tệp tc/, kèm tệp ví dụ; (C) sáu "thẻ sự kiện" để đọc như đọc chữ.
@ps Get-ChildItem tc/*.evtx | ForEach-Object { $f = $_.Name; evtx-rec $_.FullName 2>$null | ConvertFrom-Json | ForEach-Object { [pscustomobject]@{ K = $_.kenh -replace 'Microsoft-Windows-',''; Id = $_.id; F = $f } } } | Group-Object K,Id | Where-Object { $_.Name -match ', (4624|4625|4672|4688|4697|4698|4702|4719|4720|4722|4726|4732|4738|4778|4779|4825|1102|104|7036|7040|7045|1116|1117|5007|1149|21|24|25|4104|4616)$' } | Sort-Object { [int]($_.Name -split ', ')[1] } | ForEach-Object { '{0,-52} {1,5}  ví dụ: {2}' -f $_.Name, $_.Count, $_.Group[0].F }
@ps 'A', (evtx-rec tc/smb-doan-mk-4625.evtx | ConvertFrom-Json | Select-Object -Index 1000 | Select-Object t,id,kenh,may,@{n='d';e={$_.data | Select-Object TargetUserName,LogonType,Status,SubStatus,IpAddress,WorkstationName}} | ConvertTo-Json -Compress -Depth 3)
@ps 'B', (evtx-rec tc/psexec-msf-system.evtx | ConvertFrom-Json | Where-Object id -eq 7045 | Select-Object -First 1 t,id,kenh,@{n='d';e={$_.data}} | ConvertTo-Json -Compress -Depth 3)
@ps 'C', (evtx-rec tc/rdp-hijack-yamato.evtx | ConvertFrom-Json | Where-Object id -eq 4697 | Select-Object t,id,kenh,@{n='d';e={$_.data | Select-Object SubjectUserName,ServiceName,ServiceFileName,ServiceStartType,ServiceAccount}} | ConvertTo-Json -Compress -Depth 3)
@ps 'D', (evtx-rec tc/new-user.evtx | ConvertFrom-Json | Where-Object { $_.id -eq 4732 -and $_.data.TargetUserName -eq 'Administrators' } | Select-Object t,id,kenh,may,@{n='d';e={$_.data | Select-Object SubjectUserName,TargetUserName,MemberSid}} | ConvertTo-Json -Compress -Depth 3)
@ps 'E', (evtx-rec tc/guest-4722.evtx | ConvertFrom-Json | Select-Object t,id,kenh,may,@{n='d';e={$_.data | Select-Object SubjectUserName,TargetUserName,TargetSid}} | ConvertTo-Json -Compress -Depth 3)
@ps 'F', (evtx-rec tc/clear-1102.evtx | ConvertFrom-Json | Where-Object id -eq 1102 | Select-Object t,id,kenh,may,@{n='d';e={$_.data}} | ConvertTo-Json -Compress -Depth 3)
